      '<div class="ro navy big"><div class="l">Medicare spending 2024</div><div class="v">' + fmt(m.sp[4]) + '</div><div class="s">' + (m.cagr !== null ? pct(m.cagr, 0) + " a year since 2020; " : "") + n(m.cl[4]) + " claims, " + n(m.be[4]) + " beneficiaries in 2024</div></div></div>";
    out += '<div class="grid2">' + pane('<p class="label">Spending 2020 to 2024, millions</p>' + lines([{ label: "Medicare", color: acol(m.area), points: pts, dots: true }], { fmt: fmt, xticks: [2020, 2021, 2022, 2023, 2024], cap: "Gross " + (m.part === "B" ? "allowed charges, Part B" : "drug cost, Part D, before manufacturer rebates") + ". Source: CMS Medicare " + (m.part === "B" ? "Part B" : "Part D") + " Spending by Drug, data year 2024." })) +
      pane('<p class="label">Beneficiaries and average spend per beneficiary</p>' + lines([{ label: "Beneficiaries", color: "var(--blue)", points: m.be.map(function (v, i) { return [2020 + i, v || 0]; }), dots: true }], { xticks: [2020, 2021, 2022, 2023, 2024], cap: "Spend per beneficiary in 2024: " + (m.be[4] ? "$" + n(m.sp[4] * 1e6 / m.be[4]) : "n/a") + "; per claim: " + (m.cl[4] ? "$" + n(m.sp[4] * 1e6 / m.cl[4]) : "n/a") + "." })) + "</div>";
    if (m.makers.length) out += pane('<p class="label">Who is paid for it</p>' + table(["Manufacturer", "#Medicare 2024", "#Share", "Filer"], m.makers.map(function (k) { var co = D.makers.filter(function (x) { return x.name === k.name || x.name === k.name + " (Part B)"; })[0]; return [co ? '<a href="#/company/' + esc(co.id) + '"><b>' + esc(k.name) + "</b></a>" : "<b>" + esc(k.name) + "</b>", fmt(k.sp), pct(k.share), k.ticker ? '<a href="#/companies?t=' + esc(k.ticker) + '">' + esc(k.ticker) + "</a>" : '<span class="small">not a 10-K filer in the feed</span>']; })) + (maker ? '<p class="small">' + esc(clean(m.brand)) + " is " + pct(m.sp[4] / maker.sp[4]) + " of " + esc(maker.name) + "'s Medicare book of " + fmt(maker.sp[4]) + " in 2024" + (siblings.length ? "; its other large lines are " + siblings.map(function (t) { return '<a href="#/molecule/' + esc(t.id) + '">' + esc(clean(t.brand)) + "</a>"; }).join(", ") : "") + ".</p>" : ""));
    if (m.loe || m.negotiation) out += '<div class="grid2">' + (m.loe ? pane('<p class="label">Exclusivity</p><p><b>' + m.loe.year + "</b>. " + esc(m.loe.note) + '</p><p class="small">Source: ' + esc(m.loe.source) + ". Status: " + esc(m.loe.status) + ".</p>", m.loe.status === "unverified" ? "amb" : "") : "") + (m.negotiation ? pane('<p class="label">Medicare negotiation</p><p>Selected in cycle ' + m.negotiation.cycle + "; the negotiated price applies from " + esc(m.negotiation.effective) + (m.negotiation.mfp ? ", at $" + n(m.negotiation.mfp) + " for a 30-day supply" : "; the price is due for publication by 30 November 2026") + '.</p><p class="small">Source: ' + esc(D.negotiation[m.negotiation.cycle - 1].source) + "</p>") : "") + "</div>";
