    out += '<div class="pn"><a class="btn sm" href="#/molecules">← All molecules</a>' + D.molecules.filter(function (x) { return x.area === m.area && x.id !== m.id; }).slice(0, 8).map(function (x) { return '<a class="btn sm" href="#/molecule/' + esc(x.id) + '">' + esc(clean(x.brand)) + "</a>"; }).join("") + "</div>";
