    out += '<div class="section">' + vhead("Listed filers, <em>quarter by quarter</em>", "Revenue and, where reported, research and development from 10-Q and 10-K filings, refreshed daily from SEC EDGAR. Millions of dollars per quarter; click a company for its series.") +
      gnames.map(function (g) { return '<h3>' + esc(g) + "</h3>" + '<div class="mcards">' + groups[g].map(function (c) { var last = c.rev[c.rev.length - 1], first = c.rev[0]; return '<a class="mcard" href="#/companies?t=' + esc(c.ticker) + '"><div class="n"><span>' + esc(c.ticker) + "</span><span>" + esc(last ? last[0] : "") + '</span></div><h3>' + esc(c.name) + '</h3><p>' + (c.latest ? "latest " + esc(c.latest.form) + " filed " + esc(c.latest.filed) : "") + '</p><div class="v">' + (last ? fmt(last[2]) : "n/a") + '</div><div class="sub">revenue, latest quarter' + (first && last && first[2] > 0 ? "; " + pct(last[2] / first[2] - 1) + " over " + c.rev.length + " quarters" : "") + "</div>" + (c.rev.length > 2 ? spark(c.rev.map(function (r) { return r[2]; }), "var(--accent)") : "") + "</a>"; }).join("") + "</div>"; }).join("") + "</div>";
