    return '<div class="pane hi"><div class="cohead"><div><p class="label">' + esc(co.group) + " · " + esc(co.ticker) + " · CIK " + co.cik + '</p><h2>' + esc(co.name) + '</h2><p>' + esc(co.entity) + '. Quarterly figures from the company\'s 10-Q and 10-K filings, latest ' + (co.latestFiling ? esc(co.latestFiling.form) + " filed " + esc(co.latestFiling.filed) : "n/a") + '. <a href="' + esc(co.filingsUrl) + '" target="_blank" rel="noopener">Filings at EDGAR</a> · <a href="' + esc(co.factsUrl) + '" target="_blank" rel="noopener">Company facts JSON</a></p></div>' +
      ro("Revenue, latest quarter", fmt(s.revenue[s.revenue.length - 1][2]), esc(s.revenue[s.revenue.length - 1][0]) + (s.rnd ? "; R&D " + fmt(s.rnd[s.rnd.length - 1][2]) + " (" + pct(s.rnd[s.rnd.length - 1][2] / s.revenue[s.revenue.length - 1][2]) + " of revenue)" : ""), "navy") + "</div>" +
      '<div class="grid2">' + keys.map(function (k) { var pts = s[k].filter(function (p) { return p[0] >= "2016Q1"; }).map(function (p) { var q = /^(\d{4})Q(\d)$/.exec(p[0]); return [(+q[1]) + ((+q[2]) - 1) / 4, p[2]]; }); return '<div><p class="label">' + NAMES[k] + ", millions per quarter</p>" + lines([{ label: NAMES[k], color: k === "rnd" ? "var(--vio)" : "var(--accent)", points: pts }], { w: innerWidth < 720 ? 400 : 560, height: 200, fmt: fmt, xfmt: function (v) { return Math.floor(v); }, xticks: [2016, 2018, 2020, 2022, 2024, 2026], cap: "Tags: " + esc((co.tags[k] || []).join(", ")) }) + "</div>"; }).join("") + "</div></div>";
