    out += '<div class="grid2">' + pane('<p class="label">The book, by line</p>' + hbars(k.top.map(function (t, i) { return { label: clean(t.brand), v: t.sp, color: colors[i % 8] }; }), { fmt: fmt, cap: "2024 Medicare spending by line; the rest of the book is " + fmt(k.sp[4] - k.top.reduce(function (s, t) { return s + t.sp; }, 0)) + " across " + Math.max(0, k.n - k.top.length) + " smaller lines." })) +
      pane('<p class="label">The book over time</p>' + lines([{ label: "Medicare, all lines", color: "var(--accent)", points: k.sp.map(function (v, i) { return [2020 + i, v]; }), dots: true }], { fmt: fmt, xticks: [2020, 2021, 2022, 2023, 2024], cap: "Sum of the maker's lines in the Part D file" + (k.name.indexOf("(Part B)") > 0 ? " (Part B lines attributed by the publisher)" : "") + "." })) + "</div>";
    out += pane('<p class="label">Lines</p>' + table(["Line", "Generic", "#Medicare 2024", "#Share of book", "Exclusivity", "Negotiation"], k.top.map(function (t) { var m = molById(t.id), l = D.loe[t.brand]; return ['<a href="#/molecule/' + esc(t.id) + '"><b>' + esc(clean(t.brand)) + "</b></a>", esc(t.gen || ""), fmt(t.sp), pct(t.share), l ? l.year + (l.status === "unverified" ? " (unverified)" : "") : "", m && m.negotiation ? "from " + esc(m.negotiation.effective.slice(0, 4)) : ""]; })));
    if (co) out += filerBlock(co); else out += '<div class="banner">No SEC 10-K filer is joined to this maker: it is private, a subsidiary, or a foreign private issuer reporting under IFRS on Form 20-F, which the daily feed does not read.</div>';
    out += '<div class="pn"><a class="btn sm" href="#/companies">← All companies</a></div>';
