    $app.querySelectorAll("[data-q]").forEach(function (b) { b.addEventListener("click", function () { var kv = b.dataset.q.split("="), r2 = parse(); r2.q[kv[0]] = kv[1]; Object.keys(r2.q).forEach(function (k) { if (!r2.q[k]) delete r2.q[k]; }); location.hash = "#/" + r2.path.join("/") + (Object.keys(r2.q).length ? "?" + Object.keys(r2.q).map(function (k) { return k + "=" + encodeURIComponent(r2.q[k]); }).join("&") : ""); }); });
    if (!q.t || p[0] !== "companies") window.scrollTo(0, 0); else { var el = $app.querySelector(".pane.hi"); if (el) el.scrollIntoView({ block: "start" }); }
