  Promise.all([fetch(BASE + "data/atlas.json", { cache: "no-cache" }).then(function (r) { if (!r.ok) throw new Error("atlas " + r.status); return r.json(); }),
               (/(^|\.)abhaychakra\.com$/.test(location.hostname) ? fetch("/assets/data/lifesci.json", { cache: "no-cache" }) : fetch("data/lifesci.json", { cache: "no-cache" })).then(function (r) { return r.ok ? r.json() : null; }).catch(function () { return null; })])
    .then(function (res) { D = res[0]; FEED = res[1]; if (FEED) { D.groups = {}; FEED.companies.forEach(function (c) { (D.groups[c.group] = D.groups[c.group] || []).push({ ticker: c.ticker, name: c.name, rev: (c.series.revenue || []).slice(-16), rnd: (c.series.rnd || []).slice(-16), latest: c.latestFiling }); }); D.devices = FEED.devices || D.devices; D.macro = FEED.macro || D.macro; } render(); })
    .catch(function (e) { $app.innerHTML = '<div class="wrap"><div class="chead"><h1>The data could not be loaded</h1><p>' + esc(e.message) + ". The atlas is written to /p/healthcare/data/atlas.json at build time.</p></div></div>"; });
